  PasswordValidated: boolean;
  WithdrawedNumber: number;
  InputCard: BankCard;
  CardIDValidated: boolean;
  IsDeposit: boolean;
  IsWithdraw: boolean;
  DepositedNumber: number;
  /*SystemVariable End*/

  /*if the card password and id is validated, and the input card exist, show the input card balance*/
  checkBalance(): number {
    /*Definition Start*/
    let inputCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (o: any) =>
            l({
              logic: () => o.Password === this.InputCard.Password,
              description: "o.Password=InputCard.Password",
            })
              .and({
                logic: () => o.CardIDValidated === true,
                description: "o.CardIDValidated=true",
              })
              .build().pass,
        ),
      description:
        "BankCard.allInstance()->any(o|o.Password=InputCard.Passwordando.CardIDValidated=true)",
    }).build().pass;
    let isCardValid: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(inputCard) === false,
      description: "inputCard.oclIsUndefined()=false",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(this.InputCard) === false,
        description: "InputCard.oclIsUndefined()=false",
      })
        .and({
          logic: () => this.PasswordValidated === true,
          description: "PasswordValidated=true",
        })
        .and({
          logic: () => this.CardIDValidated === true,
          description: "CardIDValidated=true",
        })
        .and({
          logic: () => isCardValid === true,
          description: "isCardValid=true",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let balance: number;
    return l({
      execute: () => (balance = inputCard.Balance),
      description: "balance=inputCard.Balance",
    })
      .and({
        execute: () => balance,
        description: "result=balance",
      })
      .build().value;
    /*Postcondition End*/
  }
}
